const BATCH=4,RETRIES=3,QUIET=6000;
/* Background downloads yield to the child: any tap/voice in the page marks 'busy'; in-flight background fetches are
   aborted and nothing new starts until the page has been quiet for QUIET ms, so voice clips never wait in a queue. */
let lastBusy=0;const inflight=new Set();const sleep=ms=>new Promise(z=>setTimeout(z,ms));
function markBusy(){lastBusy=Date.now();for(const a of inflight)try{a.abort()}catch(e){};inflight.clear()}
try{new BroadcastChannel('emma-prio').onmessage=markBusy}catch(e){}
/* A newer version is downloading or waiting: stop background work so it can take over right away. */
const updating=()=>!!(self.registration&&self.registration.active&&(self.registration.waiting||self.registration.installing));
async function gate(){while(Date.now()-lastBusy<QUIET)await sleep(400)}
async function getOne(c,u,urgent){for(let t=0;t<RETRIES;){if(!urgent)await gate();const ac=new AbortController();if(!urgent)inflight.add(ac);
 try{const r=await fetch(u,{cache:'reload',signal:ac.signal});if(r.ok){const b=await r.blob();await c.put(u,new Response(b,{status:200,headers:r.headers}));return true}}
 catch(e){if(ac.signal.aborted){continue}}finally{inflight.delete(ac)}
 t++;await sleep(500*t)}return false}
async function precache(){const c=await caches.open(CACHE);const todo=[];for(const u of ASSETS){if(!(await c.match(u)))todo.push(u)}
 // reuse unchanged files from the previous cache to save data
 const old=(await caches.keys()).filter(k=>k.startsWith('emma-house-')&&k!==CACHE);
 /* only a file whose bytes are unchanged (same SHA-256 as this build) is reused; a changed file with the same name
    (e.g. world.js) must come from the network, otherwise the new version would run with old code */
 const REV=new Map(ASSETS.map((u,i)=>[u,REVS[i]]));
 const hex=b=>Array.from(new Uint8Array(b),x=>x.toString(16).padStart(2,'0')).join('');
 for(const k of old){const oc=await caches.open(k);for(let i=todo.length-1;i>=0;i--){const u=todo[i];const want=REV.get(u);if(!want)continue;
  const r=await oc.match(u);if(!r)continue;let same=false;try{same=hex(await crypto.subtle.digest('SHA-256',await r.clone().arrayBuffer())).slice(0,16)===want}catch(e){}
  if(same){await c.put(u,r);todo.splice(i,1)}}}
 const failed=[];for(let i=0;i<todo.length;i+=BATCH){const part=todo.slice(i,i+BATCH);const ok=await Promise.all(part.map(u=>getOne(c,u)));part.forEach((u,j)=>ok[j]||failed.push(u))}
 if(failed.length)throw new Error('precache failed: '+failed.length+' files, e.g. '+failed[0])}
async function cacheVoicePack(id){
  const list=VOICE_PACKS[id]; if(!list||!list.length)return {ok:false,id,n:0};
  const c=await caches.open(CACHE); let n=0;
  for(let i=0;i<list.length;i+=BATCH){if(updating())break;
    const part=list.slice(i,i+BATCH);
    const ok=await Promise.all(part.map(u=>caches.match(u,{ignoreSearch:true}).then(r=>r?true:getOne(c,u,true))));
    ok.forEach(x=>{if(x)n++});
  }
  return {ok:n>0,id,n,total:list.length};
}
/* ---- Bible books: full book cached on first open; all listed books prefetched when online ---- */
const vUrl=(id,h)=>'./voice/'+(id&&id!=='mia'?id+'/':'')+h+'.mp3';
async function refreshManifest(){try{const r=await fetch('./bible-manifest.json',{cache:'no-store'});if(r.ok){const j=await r.json();if(j&&j.books)BOOKS=j.books}}catch(e){}return BOOKS}
const marker=(slug,v,id)=>'./__book__/'+slug+'/'+v+'/'+(id||'mia');
const busy={};
async function cacheBook(slug,id){const b=BOOKS[slug];if(!b)return {slug,ok:false,missing:true};
 const key=slug+'|'+(id||'mia');if(busy[key])return busy[key];
 return busy[key]=(async()=>{try{const c=await caches.open(BOOKS_CACHE);const mk=marker(slug,b.v,id);
  if(await c.match(mk))return {slug,ok:true,cached:true};
  const ids=[...new Set(['mia',id||'mia'])];
  const urls=[...b.files,...ids.flatMap(i=>b.voice.map(h=>vUrl(i,h)))];
  let fail=0;for(let i=0;i<urls.length;i+=BATCH){if(updating()){fail++;break}const part=urls.slice(i,i+BATCH);const ok=await Promise.all(part.map(u=>getOne(c,u)));ok.forEach(x=>{if(!x)fail++})}
  if(!fail)await c.put(mk,new Response(BUILD));
  return {slug,ok:!fail,n:urls.length,fail}}finally{delete busy[key]}})()}
async function cacheAllBooks(id){await refreshManifest();const res=[];for(const s of Object.keys(BOOKS)){if(updating())break;res.push(await cacheBook(s,id))}return res}
async function tell(msg,src){const cl=await self.clients.matchAll({type:'window'});cl.forEach(c=>c.postMessage(msg));}
self.addEventListener('install',e=>e.waitUntil(precache()));
self.addEventListener('activate',e=>e.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith('emma-house-')&&k!==CACHE)await caches.delete(k);await self.clients.claim()})()));
self.addEventListener('message',e=>{
  const d=e.data;
  if(d==='skipWaiting')self.skipWaiting();
  if(d&&d.type==='busy')markBusy();
  if(d==='build')e.source&&e.source.postMessage({build:BUILD});
  if(d&&d.type==='cacheVoice'){
    e.waitUntil((async()=>{const r=await cacheVoicePack(d.id);tell({type:'voiceCached',...r})})());
  }
  if(d&&d.type==='cacheBook'){e.waitUntil((async()=>{const r=await cacheBook(d.slug,d.voice);tell({type:'bookCached',...r})})())}
  if(d&&d.type==='cacheBooks'){/* no waitUntil: a long background download must never block a new version */(async()=>{const r=await cacheAllBooks(d.voice);tell({type:'booksCached',books:r})})()}
});
async function rangeResp(r,range){const b=await r.blob();const m=/bytes=(\d*)-(\d*)/.exec(range);let s=m&&m[1]?+m[1]:0,end=m&&m[2]?+m[2]:b.size-1;if(end>=b.size)end=b.size-1;
 return new Response(b.slice(s,end+1),{status:206,headers:{'Content-Type':r.headers.get('Content-Type')||'audio/mpeg','Content-Range':`bytes ${s}-${end}/${b.size}`,'Content-Length':String(end-s+1),'Accept-Ranges':'bytes'}})}
self.addEventListener('fetch',e=>{const req=e.request;if(req.method!=='GET')return;const url=new URL(req.url);if(url.origin!==location.origin)return;
 if(url.pathname.endsWith('/bible-manifest.json'))return; /* always live when online */
 /* content library catalog: the only content file that changes in place -> network first, cached copy offline.
    Every other content/library file has its content hash in its name, so cache-first below is always correct. */
 if(url.pathname.endsWith('/content/library/catalog.json')){e.respondWith((async()=>{const key='./content/library/catalog.json';
  try{const n=await fetch(req.url,{cache:'no-store'});if(n.ok){const cp=n.clone();(await caches.open(CACHE)).put(key,cp);return n}throw new Error(n.status)}
  catch(err){return (await caches.match(key,{ignoreSearch:true}))||new Response('',{status:504})}})());return}
 e.respondWith((async()=>{const c=await caches.open(CACHE);
  let r=req.mode==='navigate'?(await c.match('./index.html')||await c.match('./')):(await c.match(req.url,{ignoreSearch:true,ignoreVary:true})||await caches.match(req.url,{ignoreSearch:true,ignoreVary:true}));
  if(!r&&req.mode!=='navigate'){try{const n=await fetch(req);if(n.ok&&n.status===200&&!req.headers.get('range')){const dst=url.pathname.includes('/img/bible/')?await caches.open(BOOKS_CACHE):c;dst.put(req.url,n.clone())}return n}catch(err){/* offline + this voice pack not fully downloaded yet: use Mia's cached clip instead of silence */const vm=/\/voice\/[a-z]+\/([0-9a-f]{8}\.mp3)$/.exec(url.pathname);if(vm){const m=await caches.match('./voice/'+vm[1],{ignoreSearch:true});if(m){const range=req.headers.get('range');return range?rangeResp(m,range):m}}return new Response('',{status:504})}}
  if(!r){try{return await fetch(req)}catch(err){return new Response('Offline',{status:503})}}
  const range=req.headers.get('range');return range?rangeResp(r,range):r})())});
